{"status": "success", "output": "def transform(grid):
    """Extend each diagonal run of matching non-background cells at both ends."""
    from collections import Counter

    out = [row[:] for row in grid]
    h, w = len(out), len(out[0]) if out else 0
    if not h or not w:
        return out
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    segments = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    segments.append((r, c, dr, dc, color))

    for r, c, dr, dc, color in segments:
        # Extend outward from both ends of each observed diagonal pair.
        for sr, sc, step_r, step_c in ((r - dr, c - dc, -dr, -dc),
                                       (r + 2 * dr, c + 2 * dc, dr, dc)):
            nr, nc = sr, sc
            while 0 <= nr < h and 0 <= nc < w:
                if out[nr][nc] not in (background, color):
                    break
                out[nr][nc] = color
                nr += step_r
                nc += step_c
    return out
